B.Y7=s(["One ticket to Kyoto, please.","Which platform is Kyoto?","I came from Kyoto."],t.s)
B.a1I=new A.du("transport_ticket","Buy a train ticket","Transportation","I can ask for one ticket to a destination.",B.d1,B.oz,"\u4eac\u90fd\u307e\u3067\u4e00\u679a\u304a\u9858\u3044\u3057\u307e\u3059\u3002","Kyouto made ichimai onegaishimasu.","One ticket to Kyoto, please.",B.Y7,0,"\u679a is the counter used for flat items such as paper tickets.","Railway clock","\ud83d\udd70\ufe0f","directions_station")
B.Y9=s(["What is this?","How much is this?","May I try this?"],t.s)
B.a1w=new A.du("shopping_price","Ask the price","Shopping","I can ask the price and understand a simple answer.",B.d1,B.oz,"\u3053\u308c\u306f\u3044\u304f\u3089\u3067\u3059\u304b\u3002","Kore wa ikura desu ka?","How much is this?",B.Y9,1,"Place cash or cards on the payment tray when one is provided rather than handing them directly.","Market basket","\ud83e\uddfa","transport_ticket")
